-- Supplementary NEW isolated runtime unit, not a replacement for any larger BasicCare baseline.
-- Privileged synthetic Auth/native sources only; no HTTP, browser, concurrency or clinical approval claim.
-- Requires the applied base+DTO before the binding-intent followup. All writes roll back.
BEGIN;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='5s';
DO $unit$
DECLARE
 f_t uuid:=gen_random_uuid();f_c uuid:=gen_random_uuid();f_u uuid:=gen_random_uuid();f_r uuid:=gen_random_uuid();f_s uuid:=gen_random_uuid();
 f_plan uuid:=gen_random_uuid();f_version uuid:=gen_random_uuid();f_item uuid:=gen_random_uuid();f_tour uuid:=gen_random_uuid();f_stop uuid:=gen_random_uuid();f_bind_request uuid:=gen_random_uuid();f_care_request uuid:=gen_random_uuid();
 f_day date:=(clock_timestamp()at time zone 'Europe/Berlin')::date-1;f_at text;f_native jsonb;f_issue jsonb;f_binding jsonb;f_entry jsonb;f_packet jsonb;f_receipt jsonb;f_confirmed jsonb;f_finished boolean:=false;
BEGIN
 BEGIN
  IF to_regclass('care_private.basic_care_binding_intents')IS NOT NULL THEN RAISE EXCEPTION 'Run this supplementary baseline unit before the binding-intent followup';END IF;
  INSERT INTO public.tenants(id,name)VALUES(f_t,'Synthetic isolated BasicCare receipt unit');
  INSERT INTO public.roles(id,key,name)VALUES(f_r,'synthetic_basic_unit_'||f_r,'Synthetic native planning author');
  INSERT INTO public.role_permissions(role_id,permission_key)SELECT f_r,unnest(ARRAY['pflege.plans.view','pflege.plans.manage','pflege.documentation.view','pflege.documentation.create']);
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data)VALUES(f_u,f_u||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=f_t,role_id=f_r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic isolated receipt author'WHERE id=f_u;
  INSERT INTO auth.sessions(id,user_id,not_after)VALUES(f_s,f_u,clock_timestamp()+interval '1 hour');
  INSERT INTO public.clients(id,tenant_id,first_name,last_name,status,lifecycle_status)VALUES(f_c,f_t,'Synthetic','Receipt unit client','aktiv','aktiv');
  INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active)VALUES(f_t,f_c,'pflege','active',true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',f_u,'role','authenticated','session_id',f_s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint)::text,true);
  IF auth.uid()IS DISTINCT FROM f_u OR public.resolve_current_profile_id()IS DISTINCT FROM f_u OR public.current_tenant_id()IS DISTINCT FROM f_t THEN RAISE EXCEPTION 'Synthetic own Auth/session/profile/tenant was not actually established';END IF;
  PERFORM care_private.basic_care_actor(f_t,f_c,f_u,true);
  INSERT INTO public.care_plans(id,tenant_id,client_id,title,status,valid_from,valid_until)VALUES(f_plan,f_t,f_c,'Synthetic native individual planning unit','aktiv',f_day-1,f_day+7);
  INSERT INTO public.care_plan_items(id,tenant_id,care_plan_id,category,title,intervention,status,sort_order,created_by,updated_by)VALUES(f_item,f_t,f_plan,'body_care','Synthetic explicitly planned partial body care','Synthetic individual planned assistance','active',1,f_u,f_u);
  INSERT INTO public.care_plan_versions(id,tenant_id,care_plan_id,version,snapshot,reason,actor_id,actor_name)
   SELECT f_version,f_t,f_plan,1,jsonb_build_object('plan',to_jsonb(p),'items',(SELECT jsonb_agg(to_jsonb(i)ORDER BY i.id)FROM public.care_plan_items i WHERE i.care_plan_id=f_plan)),'Synthetic full native snapshot authored explicitly',f_u,'Synthetic isolated receipt author'FROM public.care_plans p WHERE p.id=f_plan;
  INSERT INTO public.care_tours(id,tenant_id,tour_date,name,status,created_by,updated_by)VALUES(f_tour,f_t,f_day,'Synthetic published receipt-unit tour','published',f_u,f_u);
  INSERT INTO public.care_tour_stops(id,tenant_id,tour_id,sequence_no,client_id,client_name_snapshot,planned_start,planned_end,status)VALUES(f_stop,f_t,f_tour,1,f_c,'Synthetic client','08:15:30.123456','08:45:30.123456','planned');
  f_native:=care_private.basic_care_native_sources(f_t,f_c,f_version,f_item,f_stop);
  IF f_native#>>'{planVersion,id}'IS DISTINCT FROM f_version::text OR f_native#>>'{measure,id}'IS DISTINCT FROM f_item::text OR f_native#>>'{visit,id}'IS DISTINCT FROM f_stop::text OR f_native#>>'{plan,client_id}'IS DISTINCT FROM f_c::text OR f_native#>>'{visit,client_id}'IS DISTINCT FROM f_c::text OR f_native#>>'{visit,tour_id}'IS DISTINCT FROM f_tour::text OR f_native#>'{planVersion,snapshot,plan}'IS DISTINCT FROM f_native->'plan'OR f_native#>'{planVersion,snapshot,items,0}'IS DISTINCT FROM f_native->'measure'THEN RAISE EXCEPTION 'Actual full native plan/version/item/stop/tour scope mismatch';END IF;
  f_at:=to_char(((f_day+time '08:15:30.123456')at time zone 'Europe/Berlin')at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  f_issue:=jsonb_build_object('schemaVersion','1','requestId',f_bind_request,'tenantId',f_t,'clientId',f_c,'actorId',f_u,'planVersionId',f_version,'measureId',f_item,'visitId',f_stop,'plannedAt',f_at,'timeZone','Europe/Berlin','secondPersonRequired',false,'reason','Synthetic explicit planned selection without an actual care claim','sources',f_native);
  f_binding:=public.web_issue_basic_care_binding(p_packet=>f_issue);
  IF care_private.basic_care_uuid(f_binding->'bindingId')IS DISTINCT FROM true OR f_binding#>>'{plan,planVersionId}'IS DISTINCT FROM f_version::text OR f_binding#>>'{plan,measureId}'IS DISTINCT FROM f_item::text OR f_binding#>>'{plan,visitId}'IS DISTINCT FROM f_stop::text OR f_binding->>'requestId'IS DISTINCT FROM f_bind_request::text OR f_binding->'packet'IS DISTINCT FROM f_issue OR f_binding#>>'{plan,kind}'IS DISTINCT FROM 'body_care'OR f_binding#>>'{plan,title}'IS DISTINCT FROM f_native#>>'{measure,title}'OR f_binding#>>'{plan,plannedAt}'IS DISTINCT FROM f_at OR f_binding#>'{plan,secondPersonRequired}'IS DISTINCT FROM 'false'::jsonb OR f_binding#>'{plan,pressureOriginals}'IS DISTINCT FROM 'null'::jsonb OR f_binding#>'{plan,fallOriginals}'IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Native binding receipt changed the exact authored planning call';END IF;
  IF public.web_issue_basic_care_binding(f_issue)IS DISTINCT FROM f_binding THEN RAISE EXCEPTION 'Exact native binding retry changed its immutable receipt';END IF;
  f_entry:=jsonb_build_object('kind','body_care','title',f_binding#>'{plan,title}','plannedAt',f_at,'occurredAt',null,'planVersionId',f_version,'measureId',f_item,'visitId',f_stop,'planSnapshotSha256',f_binding#>'{plan,planSnapshotSha256}',
   'consent','{"state":"not_asked","recordedAt":null,"statedReason":"","consultation":""}'::jsonb,
   'assistance',jsonb_build_object('level','prompting','secondPersonRequired',false,'helpers',jsonb_build_array(f_u),'aids','[]'::jsonb,'technique','Synthetic expressly planned verbal assistance'),
   'observation','{"baseline":"Synthetic explicit individual planning situation","skin":"","mobility":"","oral":"","tolerance":"","oralAbnormality":false,"skinChange":false}'::jsonb,
   'execution','{"outcome":"planned","bodyScope":"partial","performedBy":[],"interventions":[],"result":"","deviation":""}'::jsonb,
   'prevention','{"risk":"","professionalBasis":"","individualMeasure":"","reviewAt":null,"fallOccurred":false,"incidentId":null,"reassessmentId":null}'::jsonb,
   'followUp','{"required":false,"reason":"","responsibleProfileId":null,"dueAt":null,"taskId":null,"state":"not_required","closureEvidence":""}'::jsonb,'lifecycle','open');
  f_packet:=jsonb_build_object('schemaVersion','1','action','create','requestId',f_care_request,'tenantId',f_t,'clientId',f_c,'actorId',f_u,'expectedHeadId',null,'expectedRevision',0,'entry',f_entry,'reason','','original',null,'pressureOriginals',null,'fallOriginals',null);
  f_receipt:=public.web_commit_basic_care_packet(p_packet=>f_packet);
  IF f_receipt->>'requestId'IS DISTINCT FROM f_care_request::text OR f_receipt->'packet'IS DISTINCT FROM f_packet OR f_receipt#>'{original,payload}'IS DISTINCT FROM f_entry OR f_receipt#>>'{original,tenantId}'IS DISTINCT FROM f_t::text OR f_receipt#>>'{original,clientId}'IS DISTINCT FROM f_c::text OR f_receipt#>>'{original,recordedBy}'IS DISTINCT FROM f_u::text OR f_receipt#>>'{original,id}'IS DISTINCT FROM f_receipt#>>'{original,headId}'OR f_receipt#>>'{original,revision}'IS DISTINCT FROM '1'OR jsonb_array_length(f_receipt#>'{original,history}')IS DISTINCT FROM 1 OR f_receipt#>>'{original,rootId}'IS DISTINCT FROM f_receipt#>>'{original,headId}'OR f_receipt#>>'{original,history,0,id}'IS DISTINCT FROM f_receipt#>>'{original,headId}'OR f_receipt#>'{original,history,0,payload}'IS DISTINCT FROM f_entry THEN RAISE EXCEPTION 'Actual planned-care original or exact own receipt mismatch';END IF;
  IF public.web_commit_basic_care_packet(f_packet)IS DISTINCT FROM f_receipt THEN RAISE EXCEPTION 'Exact planned-care retry changed the stored own original';END IF;
  f_confirmed:=public.web_confirm_basic_care_packet(p_tenant_id=>f_t,p_client_id=>f_c,p_actor_profile_id=>f_u,p_request_id=>f_care_request,p_packet=>f_packet);
  IF f_confirmed IS DISTINCT FROM f_receipt THEN RAISE EXCEPTION 'Own exact confirmation returned a different original';END IF;
  BEGIN PERFORM public.web_confirm_basic_care_packet(f_t,f_c,f_u,gen_random_uuid(),f_packet);RAISE EXCEPTION 'Unknown request adopted another own receipt';EXCEPTION WHEN SQLSTATE 'P0F02'THEN NULL;END;
  IF(SELECT count(*)FROM public.basic_care_plan_bindings WHERE tenant_id=f_t)IS DISTINCT FROM 1 OR(SELECT count(*)FROM care_private.basic_care_binding_requests WHERE tenant_id=f_t)IS DISTINCT FROM 1 OR(SELECT count(*)FROM public.basic_care_roots WHERE tenant_id=f_t)IS DISTINCT FROM 1 OR(SELECT count(*)FROM public.basic_care_events WHERE tenant_id=f_t)IS DISTINCT FROM 1 OR(SELECT count(*)FROM public.basic_care_receipts WHERE tenant_id=f_t)IS DISTINCT FROM 1 OR EXISTS(SELECT 1 FROM public.basic_care_review_events WHERE tenant_id=f_t)OR care_private.basic_care_native_sources(f_t,f_c,f_version,f_item,f_stop)IS DISTINCT FROM f_native THEN RAISE EXCEPTION 'Retries duplicated data or changed native planning';END IF;
  f_finished:=true;RAISE EXCEPTION USING ERRCODE='Z0001';
 EXCEPTION WHEN SQLSTATE 'Z0001'THEN NULL;END;
 IF f_finished IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM public.tenants WHERE id=f_t)OR EXISTS(SELECT 1 FROM auth.users WHERE id=f_u)OR EXISTS(SELECT 1 FROM auth.sessions WHERE id=f_s)OR EXISTS(SELECT 1 FROM public.profiles WHERE id=f_u)OR EXISTS(SELECT 1 FROM public.roles WHERE id=f_r)OR EXISTS(SELECT 1 FROM public.role_permissions WHERE role_id=f_r)OR EXISTS(SELECT 1 FROM public.role_permission_sets WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.clients WHERE id=f_c)OR EXISTS(SELECT 1 FROM public.client_module_assignments WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.care_plans WHERE id=f_plan)OR EXISTS(SELECT 1 FROM public.care_plan_versions WHERE id=f_version)OR EXISTS(SELECT 1 FROM public.care_plan_items WHERE id=f_item)OR EXISTS(SELECT 1 FROM public.care_tours WHERE id=f_tour)OR EXISTS(SELECT 1 FROM public.care_tour_stops WHERE id=f_stop)OR EXISTS(SELECT 1 FROM care_private.basic_care_binding_requests WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_plan_bindings WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_roots WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_events WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_receipts WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_review_roots WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_review_events WHERE tenant_id=f_t)OR EXISTS(SELECT 1 FROM public.basic_care_review_receipts WHERE tenant_id=f_t)THEN RAISE EXCEPTION 'Supplementary isolated unit full rollback cleanup failed';END IF;
 PERFORM set_config('cp365.basic_binding_receipt_unit',jsonb_build_object('expected',jsonb_build_object('tenantId',f_t,'clientId',f_c,'authorId',f_u,'planVersionId',f_version,'measureId',f_item,'visitId',f_stop,'issueRequestId',f_bind_request,'createRequestId',f_care_request),'issuePacket',f_issue,'issueReceipt',f_binding,'packet',f_packet,'receipt',f_receipt,'confirmedReceipt',f_confirmed,'rollbackCleanupPassed',true,'supplementaryRuntimeUnit',true)::text,true);
END
$unit$;
SELECT current_setting('cp365.basic_binding_receipt_unit',true)::jsonb AS synthetic_evidence;
ROLLBACK;
